# Koszul homology of monomial modules U/V over k[x_1..x_n] (U, V monomial ideals, V inside U), graded, exact rank mod a large prime.
from itertools import combinations, product
P = 2147483647
def rank(rows, ncols):
    rows = [dict(r) for r in rows if r]
    piv = {}; r = 0
    for row in rows:
        row = {c: v % P for c, v in row.items() if v % P}
        while row:
            c = min(row)
            if c in piv:
                prow = piv[c]; f = row[c]
                for cc, vv in prow.items():
                    nv = (row.get(cc, 0) - f * vv) % P
                    if nv: row[cc] = nv
                    else: row.pop(cc, None)
            else:
                inv = pow(row[c], P - 2, P)
                piv[c] = {cc: vv * inv % P for cc, vv in row.items()}
                r += 1; break
    return r
def monos(n, d):
    if n == 0: return [()] if d == 0 else []
    return [(a,) + m for a in range(d + 1) for m in monos(n - 1, d - a)]
def divides(g, m): return all(a <= b for a, b in zip(g, m))
def inI(gens, m): return any(divides(g, m) for g in gens)
def koszul_H(n, U, V, T):
    """dims of H_i(x_1..x_n; U/V) summed over internal degrees <= T. U, V: lists of exponent tuples (U=None means whole ring)."""
    def inM(m): return (U is None or inI(U, m)) and not inI(V, m)
    H = [0] * (n + 1)
    for t in range(T + 1):
        # K_i in internal degree t: pairs (m, S) with |S| = i, deg m = t - i
        B = []
        for i in range(n + 1):
            d = t - i
            B.append([(m, S) for S in combinations(range(n), i) for m in (monos(n, d) if d >= 0 else []) if inM(m)])
        idx = [{b: j for j, b in enumerate(Bi)} for Bi in B]
        rk = [0] * (n + 2)
        for i in range(1, n + 1):
            rows = []
            for (m, S) in B[i]:
                row = {}
                for pos, s in enumerate(S):
                    mm = list(m); mm[s] += 1; mm = tuple(mm)
                    if inM(mm):
                        key = (mm, tuple(x for x in S if x != s))
                        row[idx[i - 1][key]] = row.get(idx[i - 1][key], 0) + (-1) ** pos
                rows.append(row)
            rk[i] = rank(rows, len(B[i - 1]))
        for i in range(n + 1):
            H[i] += len(B[i]) - rk[i] - rk[i + 1]
    return H
def depth(n, U, V, T):
    H = koszul_H(n, U, V, T)
    top = max(i for i in range(n + 1) if H[i])
    return n - top, H

def basis(n, gens, d): return [m for m in monos(n, d) if not inI(gens, m)]
def mult_rank(n, gens, lin, d):
    """rank of multiplication by the linear form lin (dict var->coef) from (S/I)_d to (S/I)_{d+1}"""
    B0 = basis(n, gens, d); B1 = basis(n, gens, d + 1); idx = {b: j for j, b in enumerate(B1)}
    rows = []
    for m in B0:
        row = {}
        for v, c in lin.items():
            mm = list(m); mm[v] += 1; mm = tuple(mm)
            if mm in idx: row[idx[mm]] = row.get(idx[mm], 0) + c
        rows.append(row)
    return rank(rows, len(B1)), len(B0)

