N = 60
def sg(gens):
    S = {0}
    for s in range(1, N):
        if any(s - g in S for g in gens if s - g >= 0): S.add(s)
    return S
def apery(S, a): return sorted(s for s in S if s < N - 10 and (s - a) not in S)
def socle(S, a):
    A = apery(S, a)
    # t^s (s in Apery set) is in the socle of R/t^aR iff s + g is not in the Apery set for every generator-type element g>0 of S
    return [s for s in A if all((s + g) not in A for g in S if 0 < g < N - 20 and s + g < N - 10)]
