assert apery(S345, 3) == [0,4,5] and apery(S23, 2) == [0,3] and apery(S34, 3) == [0,4,8]
assert socle(S345, 3) == [4,5] and socle(S23, 2) == [3] and socle(S34, 3) == [8]
assert sorted(set(range(1, 20)) - S345) == [1, 2] and sorted(set(range(1, 20)) - S34) == [1, 2, 5]
